struct timespec req = { 1, 500000000 }; // 1.5s request
struct timespec rem;
int status;

// 1. Relative Sleep (0 flag), CLOCK_MONOTONIC
status = clock_nanosleep(CLOCK_MONOTONIC, 0, &req, &rem);

if (status == EINTR) {
    // Sleep interrupted: Continue with remaining time
    clock_nanosleep(CLOCK_MONOTONIC, 0, &rem, NULL);
}

// 2. Absolute Sleep (TIMER_ABSTIME)
struct timespec target;
clock_gettime(CLOCK_REALTIME, &target);
target.tv_sec += 5; // Target: 5 seconds from now

clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &target, NULL);
